class Lk{constructor(){this.switcherClass="lk-switcher";this.authUrl="https://lk.toplivnaya-karta.ru";this.api=new ApiClient("toplivnayakarta");this.forms=document.querySelectorAll(".lk-form");this.btn=document.querySelector(".js-auth-modal");this.init()}init(){this.api.getUser().then(isAuthenticated=>{if(isAuthenticated){if(this.btn!==null){this.btn.removeAttribute("data-modal");this.btn.href=this.authUrl}}else{this.switcher=new Switcher(this.switcherClass);this.forms.forEach(form=>{form.addEventListener("submit",e=>this.handleAuth(e))})}})}handleAuth(e){e.preventDefault();const form=e.currentTarget;const phone=form.querySelector('[name="phone"]');const login=form.querySelector('[name="login"]');const password=form.querySelector('[name="password"]');if(form.id==="lk-login-form"){if(login!==null&&password!==null){this.api.authorize(login.value,password.value).catch(error=>{const errorElement=document.querySelector(".error-message");errorElement.innerHTML=error.message;errorElement.style.display="block"})}}else{if(phone!==null){this.api.mobileAuth("toplivnaya-karta.ru",phone.value).catch(error=>{const errorElement=document.querySelector(".error-message");errorElement.innerHTML=error.message;errorElement.style.display="block"})}}}}